# Giochi Konsol OS v1.2 — /etc/giochi/buttons.map (secao 2.2).
#
# Mapeamento canonico entre os nomes usados por metadata.json ("buttons_map")
# e os codigos evdev. O Launcher NUNCA toca pinos de hardware: le
# /dev/input/event* e traduz pelo mapa carregado.
#
# Formato: <nome> = <CODIGO_EVDEV>
# Nomes obrigatorios: up down left right a b x y l r start select home

[default]
up      = BTN_DPAD_UP
down    = BTN_DPAD_DOWN
left    = BTN_DPAD_LEFT
right   = BTN_DPAD_RIGHT
a       = BTN_EAST
b       = BTN_SOUTH
x       = BTN_WEST
y       = BTN_NORTH
l       = BTN_TL
r       = BTN_TR
start   = BTN_START
select  = BTN_SELECT
home    = BTN_MODE

# X35S/X35H remapeiam A/B/X/Y no DTS (hardware-e-drivers.md §1). O mapa abaixo
# preserva a semantica do console (A = confirmar) independente do rotulo.
[x35s]
up      = BTN_DPAD_UP
down    = BTN_DPAD_DOWN
left    = BTN_DPAD_LEFT
right   = BTN_DPAD_RIGHT
a       = BTN_SOUTH
b       = BTN_EAST
x       = BTN_NORTH
y       = BTN_WEST
l       = BTN_TL
r       = BTN_TR
start   = BTN_START
select  = BTN_SELECT
home    = BTN_MODE
